// Oracle replay for the publisher's two daemon phases: the notification drain
// (`review_notify`) and the off-lock coverage refresher (`backfill_coverage`).
//
// The vectors are generated by `apps/crq-python/notify_coverage_vector_emit_b1.py`
// from the real Python control flow with injected fakes, so this file proves the
// TypeScript ports (`src/policy/crq/notifyDrain.ts`,
// `src/policy/crq/coverageSnapshot.ts`, `src/ops/crq/notifyDrain.ts`,
// `src/ops/crq/coverageRefresh.ts`) agree with the Python publisher at the same
// commit: selected rows, delivered messages, queue documents, snapshot outcomes,
// marker lifecycle and the wake decision.
//
// Classification: `process` in test/suite-classes.json, because one test runs the
// emitter's `--check` through python3 to prove the fixture is not stale.
import { execFileSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, test } from 'vitest';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  toPlainJson,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';
import {
  ledgerCanonicalBytes,
  ledgerCreditable,
  ledgerLoads,
} from '../../../src/policy/crq/ledger.js';
import {
  coverageFailed,
  coverageLiveTargets,
  coverageLoad,
  coveragePendingTargets,
  coveragePrefixDigest,
  coverageSnapshotDocument,
  parseCoverageSnapshot,
} from '../../../src/policy/crq/coverageSnapshot.js';
import {
  notifyDestination,
  notifyMessage,
  notifyValidation,
  pythonIsoformatUtc,
} from '../../../src/policy/crq/notifyDrain.js';
import { drainNotifications } from '../../../src/ops/crq/notifyDrain.js';
import {
  refreshCoverage,
  runCoverageRefresh,
  type CoverageRepository,
  type CoverageRunEffects,
} from '../../../src/ops/crq/coverageRefresh.js';
import { parseQueueBytes } from '../../../src/ops/crq/publishRun.js';

const FIXTURE = new URL(
  '../../../apps/crq-python/fixtures/crq-notify-coverage-b1/vectors.json',
  import.meta.url,
);
const EMITTER = new URL(
  '../../../apps/crq-python/notify_coverage_vector_emit_b1.py',
  import.meta.url,
);

interface VectorCase {
  readonly family: string;
  readonly name: string;
  readonly source: string;
  readonly input: JsonObject;
  readonly expect: JsonObject;
}

function objectAt(value: JsonValue | undefined, what: string): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error(`${what} is not an object`);
  return value;
}

function stringAt(value: JsonValue | undefined, what: string): string {
  if (typeof value !== 'string') throw new Error(`${what} is not a string`);
  return value;
}

function numberAt(value: JsonValue | undefined, what: string): number {
  if (!(value instanceof JsonNumber) || value.kind !== 'int') {
    throw new Error(`${what} is not an integer`);
  }
  return Number(value.integer);
}

function arrayAt(value: JsonValue | undefined, what: string): JsonValue[] {
  if (!Array.isArray(value)) throw new Error(`${what} is not an array`);
  return value;
}

/** The Python document's fields as plain JSON, for structural comparison. */
function plain(value: JsonValue | undefined): unknown {
  return value === undefined ? undefined : toPlainJson(value);
}

const document = parseJsonValue(readFileSync(FIXTURE, 'utf8'));
if (!(document instanceof JsonObject)) throw new Error('vector document is not an object');
const clockText = stringAt(document.get('clock'), 'clock');
const CLOCK_MICROS = BigInt(Date.parse(clockText)) * 1000n;
const CLOCK_SECONDS = `${clockText.slice(0, 19)}Z`;

const cases: VectorCase[] = arrayAt(document.get('families'), 'families').flatMap((family) => {
  const entry = objectAt(family, 'family');
  const name = stringAt(entry.get('family'), 'family name');
  return arrayAt(entry.get('cases'), `${name}.cases`).map((value) => {
    const item = objectAt(value, `${name} case`);
    return {
      family: name,
      name: stringAt(item.get('name'), 'case name'),
      source: stringAt(item.get('source'), 'case source'),
      input: objectAt(item.get('input'), 'case input'),
      expect: objectAt(item.get('expect'), 'case expect'),
    };
  });
});

function casesOf(family: string): VectorCase[] {
  return cases.filter((entry) => entry.family === family);
}

function withTempDir(fn: (root: string) => Promise<void> | void): Promise<void> {
  return (async () => {
    const root = mkdtempSync(join(tmpdir(), 'crq-notify-coverage-'));
    try {
      await fn(root);
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  })();
}

function addScopeLines(value: JsonObject, covered: Map<string, Set<number>>): void {
  const payload = objectAt(value.get('payload'), 'review payload');
  for (const rowValue of arrayAt(payload.get('reviewed_scope'), 'reviewed_scope')) {
    const row = objectAt(rowValue, 'reviewed_scope row');
    const name = stringAt(row.get('path'), 'reviewed path');
    const lines = covered.get(name) ?? new Set<number>();
    for (const pairValue of arrayAt(row.get('intervals'), 'intervals')) {
      const pair = arrayAt(pairValue, 'interval');
      const start = numberAt(pair[0], 'interval start');
      const end = numberAt(pair[1], 'interval end');
      for (let line = start; line <= end; line += 1) lines.add(line);
    }
    covered.set(name, lines);
  }
}

/** The Python emitter's `FakeRepo`: scripted failure plus a scripted gap. */
class FakeCoverageRepository implements CoverageRepository {
  readonly calls: JsonValue[] = [];
  constructor(
    private readonly scripted: Map<string, string>,
    private readonly gap: string | undefined,
    private readonly onFold?: () => void,
  ) {}

  beginInvocation(): void {
    this.calls.push(['begin']);
  }

  async fold(
    target: string,
    reviews: readonly JsonValue[],
    _verifyArtifact: (reference: { sha256: string; location: string }) => Promise<void>,
    covered: Map<string, Set<number>>,
    gaps: JsonValue[],
  ): Promise<void> {
    this.calls.push([
      'fold',
      target,
      reviews.map((value) => (value instanceof JsonObject ? (value.get('id') as JsonValue) : null)),
    ]);
    this.onFold?.();
    if (this.scripted.get(target) === 'raise') throw new Error('boom');
    for (const value of reviews) {
      if (!ledgerCreditable(value) || !(value instanceof JsonObject)) continue;
      if (this.gap !== undefined && value.get('id') === this.gap) {
        gaps.push(
          new JsonObject([
            ['review', value.get('id') as JsonValue],
            ['reason', 'artifact missing'],
          ]),
        );
        continue;
      }
      addScopeLines(value, covered);
    }
  }
}

function scriptedMap(input: JsonObject): Map<string, string> {
  const script = input.get('script');
  const pairs: [string, string][] =
    script instanceof JsonObject
      ? script.entries.map(([key, value]) => [key, stringAt(value, 'script action')])
      : [];
  return new Map(pairs);
}

describe('notify oracle replay (review_notify)', () => {
  for (const entry of casesOf('notify')) {
    test(entry.name, async () => {
      const input = entry.input;
      const expectValue = entry.expect;
      if (expectValue.has('destination')) {
        const value = input.get('value');
        const config = input.get('config');
        const destination = notifyDestination(value, config);
        expect(destination === undefined ? null : toPlainJson(destination)).toEqual(
          plain(expectValue.get('destination')),
        );
        if (expectValue.has('validation')) {
          expect(toPlainJson(notifyValidation(value, config))).toEqual(
            plain(expectValue.get('validation')),
          );
        }
        if (expectValue.has('validation_optional')) {
          expect(toPlainJson(notifyValidation(value, config, false))).toEqual(
            plain(expectValue.get('validation_optional')),
          );
        }
        return;
      }
      if (expectValue.has('message')) {
        const message = notifyMessage(
          objectAt(input.get('row'), 'row'),
          objectAt(input.get('event'), 'event'),
        );
        expect(message).toBe(stringAt(expectValue.get('message'), 'message'));
        return;
      }
      await withTempDir(async (stateRoot) => {
        const queuePath = join(stateRoot, 'queue.json');
        writeFileSync(queuePath, ledgerCanonicalBytes(objectAt(input.get('queue'), 'queue')));
        const replies = arrayAt(input.get('replies'), 'replies').map((value) =>
          objectAt(value, 'reply'),
        );
        const busy = arrayAt(input.get('busy'), 'busy').map((value) =>
          stringAt(value, 'busy step'),
        );
        let busyIndex = 0;
        let saves = 0;
        const sent: JsonValue[] = [];
        const selected = await drainNotifications({
          stateRoot,
          config: objectAt(input.get('config'), 'config'),
          nowMicros: () => CLOCK_MICROS,
          readQueue: async () => new Uint8Array(readFileSync(queuePath)),
          writeQueue: async (queue) => {
            saves += 1;
            writeFileSync(queuePath, ledgerCanonicalBytes(queue));
          },
          withTickLock: async <T>(fn: () => Promise<T>): Promise<T | null> => {
            const step = busy[busyIndex];
            busyIndex += 1;
            return step === 'busy' ? null : fn();
          },
          notify: async (destination, text) => {
            sent.push(
              new JsonObject([
                ['destination', destination],
                ['message', text],
              ]),
            );
            const reply = replies.shift();
            if (reply === undefined) return { paseo_send: 0 };
            if (reply.get('raised') !== undefined) throw new Error('transport down');
            const status = reply.get('paseo_send');
            return status instanceof JsonNumber
              ? { paseo_send: status.integer === null ? 0 : Number(status.integer) }
              : { paseo_send: stringAt(status, 'paseo_send') };
          },
        });
        expect(selected).toBe(numberAt(expectValue.get('selected'), 'selected'));
        expect(sent).toEqual(arrayAt(expectValue.get('sent'), 'sent'));
        expect(toPlainJson(parseQueueBytes(readFileSync(queuePath)))).toEqual(
          plain(expectValue.get('queue')),
        );
        expect(saves).toBe(numberAt(expectValue.get('saves'), 'saves'));
      });
    });
  }
});

describe('coverage refresh/load oracle replay (backfill_coverage)', () => {
  for (const entry of casesOf('coverage')) {
    test(entry.name, async () => {
      const input = entry.input;
      const expectValue = entry.expect;
      if (expectValue.has('failed')) {
        const values = arrayAt(input.get('values'), 'values');
        expect(values.map((value) => coverageFailed(value))).toEqual(
          arrayAt(expectValue.get('failed'), 'failed'),
        );
        return;
      }
      if (expectValue.has('pending')) {
        const queue = objectAt(input.get('queue'), 'queue');
        expect([...coveragePendingTargets(queue)].sort()).toEqual(
          arrayAt(expectValue.get('pending'), 'pending'),
        );
        expect([...coverageLiveTargets(queue)].sort()).toEqual(
          arrayAt(expectValue.get('live'), 'live'),
        );
        return;
      }
      if (expectValue.has('load')) {
        const events = arrayAt(input.get('events'), 'events');
        const appended = arrayAt(input.get('appended'), 'appended');
        const covered = objectAt(input.get('covered'), 'covered');
        await withTempDir(async (stateRoot) => {
          const directory = join(stateRoot, 'backfill', 'coverage');
          mkdirSync(directory, { recursive: true });
          const target = 'a'.repeat(40);
          const lines = new Map<string, Set<number>>();
          for (const [name, rows] of covered.entries) {
            const set = new Set<number>();
            for (const pairValue of arrayAt(rows, 'covered intervals')) {
              const pair = arrayAt(pairValue, 'interval');
              for (
                let line = numberAt(pair[0], 'start');
                line <= numberAt(pair[1], 'end');
                line += 1
              ) {
                set.add(line);
              }
            }
            lines.set(name, set);
          }
          writeFileSync(
            join(directory, `${target}.json`),
            ledgerCanonicalBytes(
              coverageSnapshotDocument({
                target,
                events: events.length,
                prefix: coveragePrefixDigest(events, events.length),
                covered: lines,
                gaps: [],
              }),
            ),
          );
          const snapshot = parseCoverageSnapshot(
            new Uint8Array(readFileSync(join(directory, `${target}.json`))),
            target,
          );
          const loaded = coverageLoad(snapshot, [...events, ...appended]);
          const coveredPlain: Record<string, unknown> = {};
          if (loaded !== null) {
            for (const [name, set] of loaded.covered) {
              if (set.size === 0) continue;
              coveredPlain[name] = rangesOf(set).map((pair) => toPlainJson(pair));
            }
          }
          const actual =
            loaded === null
              ? null
              : {
                  covered: coveredPlain,
                  gaps: loaded.gaps.map((gap) => toPlainJson(gap)),
                };
          expect(actual).toEqual(plain(expectValue.get('load')));
        });
        return;
      }
      await withTempDir(async (stateRoot) => {
        const directory = join(stateRoot, 'backfill', 'coverage');
        mkdirSync(directory, { recursive: true });
        const snapshot = input.get('snapshot');
        if (snapshot instanceof JsonObject) {
          const copy = new JsonObject(
            snapshot.entries.map(([key, value]) =>
              key === 'prefix' && input.get('stale_prefix') === true
                ? ([key, '0'.repeat(64)] as const)
                : ([key, value] as const),
            ),
          );
          writeFileSync(
            join(directory, `${stringAt(copy.get('target'), 'snapshot target')}.json`),
            ledgerCanonicalBytes(copy),
          );
        }
        for (const extra of arrayAt(input.get('extra_files'), 'extra_files')) {
          writeFileSync(join(directory, `${stringAt(extra, 'extra file')}.json`), '{}');
        }
        const repository = new FakeCoverageRepository(
          scriptedMap(input),
          input.get('gap') instanceof JsonObject
            ? stringAt(objectAt(input.get('gap'), 'gap').get('skip'), 'gap skip')
            : undefined,
        );
        const outcome = await refreshCoverage(
          { stateRoot, repository, verifyArtifact: async () => {} },
          arrayAt(input.get('events'), 'events'),
          arrayAt(input.get('targets'), 'targets').map((value) => stringAt(value, 'target')),
          arrayAt(input.get('keep'), 'keep').map((value) => stringAt(value, 'keep')),
        );
        expect(outcome).toEqual(plain(expectValue.get('outcome')));
        expect(repository.calls).toEqual(arrayAt(expectValue.get('calls'), 'calls'));
        expect(readdirSync(directory).sort()).toEqual(
          arrayAt(expectValue.get('remaining'), 'remaining'),
        );
        const written = expectValue.get('written');
        const target = 'a'.repeat(40);
        const writtenPath = join(directory, `${target}.json`);
        if (written === null || written === undefined) {
          expect(readdirSync(directory)).not.toContain(`${target}.json`);
          return;
        }
        expect(toPlainJson(parseQueueBytes(readFileSync(writtenPath)))).toEqual(plain(written));
      });
    });
  }
});

function rangesOf(lines: ReadonlySet<number>): JsonValue[] {
  const ranges: { start: number; end: number }[] = [];
  for (const line of [...lines].sort((left, right) => left - right)) {
    const last = ranges[ranges.length - 1];
    if (last !== undefined && last.end === line - 1) last.end = line;
    else ranges.push({ start: line, end: line });
  }
  return ranges.map((range) => [JsonNumber.int(range.start), JsonNumber.int(range.end)]);
}

describe('coverage run oracle replay (backfill_coverage.run)', () => {
  for (const entry of casesOf('run')) {
    test(entry.name, async () => {
      const input = entry.input;
      const expectValue = entry.expect;
      await withTempDir(async (stateRoot) => {
        const backfill = join(stateRoot, 'backfill');
        mkdirSync(backfill, { recursive: true });
        const requestPath = join(backfill, 'coverage-request.json');
        const request = input.get('request');
        if (request instanceof JsonObject) {
          writeFileSync(requestPath, ledgerCanonicalBytes(request));
        }
        const events = arrayAt(input.get('events'), 'events');
        const queueBytes = ledgerCanonicalBytes(objectAt(input.get('queue'), 'queue'));
        const head = 'd'.repeat(40);
        const wakes: string[] = [];
        const repository = new FakeCoverageRepository(
          new Map(),
          undefined,
          input.get('rewrite_request') === true
            ? () => {
                writeFileSync(
                  requestPath,
                  ledgerCanonicalBytes(
                    new JsonObject([
                      ['head', head],
                      ['targets', ['b'.repeat(40)]],
                    ]),
                  ),
                );
              }
            : undefined,
        );
        const settingsValue = input.get('settings');
        const effects: CoverageRunEffects = {
          stateRoot,
          repository,
          verifyArtifact: async () => {},
          settings: async () => (settingsValue instanceof JsonObject ? settingsValue : null),
          readQueue: async () => queueBytes,
          withCoverageLock: (fn) => fn(),
          withPublisherLock: (fn) => fn(),
          fetchLedger: async () => ({ head, values: events }),
          wakeSlot: async (isoSeconds) => {
            wakes.push(`next-review-at:${isoSeconds}`);
          },
          nowIso: () => CLOCK_SECONDS,
        };
        const result = await runCoverageRefresh(
          effects,
          typeof input.get('published_head') === 'string'
            ? stringAt(input.get('published_head'), 'published_head')
            : undefined,
        );
        expect(plain(new JsonObject([['result', toJson(result)]]))).toEqual(
          plain(new JsonObject([['result', expectValue.get('result') ?? null]])),
        );
        expect(wakes).toEqual(arrayAt(expectValue.get('wakes'), 'wakes'));
        expect(
          readdirSync(backfill)
            .filter((name) => name.endsWith('.json'))
            .sort(),
        ).toEqual(arrayAt(expectValue.get('remaining'), 'remaining'));
        const marker = expectValue.get('marker');
        if (marker === null || marker === undefined) {
          expect(readdirSync(backfill)).not.toContain('coverage-request.json');
        } else {
          expect(ledgerLoads(readFileSync(requestPath))).toEqual(marker);
        }
        expect(repository.calls).toEqual(arrayAt(expectValue.get('calls'), 'calls'));
      });
    });
  }
});

/** `runCoverageRefresh` results back into the JSON domain for comparison. */
function toJson(value: unknown): JsonValue {
  return parseJsonValue(JSON.stringify(value));
}

describe('policy primitives (Python datetime/isoformat parity)', () => {
  test('isoformat spells an exact second without a fraction and UTC as +00:00', () => {
    expect(pythonIsoformatUtc(CLOCK_MICROS)).toBe('2026-11-14T12:00:00+00:00');
    expect(pythonIsoformatUtc(CLOCK_MICROS + 6n)).toBe('2026-11-14T12:00:00.000006+00:00');
    expect(pythonIsoformatUtc(CLOCK_MICROS + 1_000n)).toBe('2026-11-14T12:00:00.001000+00:00');
  });

  test('a date before the epoch keeps Python floor-day arithmetic', () => {
    expect(pythonIsoformatUtc(BigInt(Date.parse('1969-12-31T23:59:59Z')) * 1000n)).toBe(
      '1969-12-31T23:59:59+00:00',
    );
  });
});

describe('oracle fixture is not stale', () => {
  test('the Python emitter reproduces the checked-in vectors', () => {
    // python3 is not required to typecheck or to replay the fixture; the
    // vectors themselves are committed evidence. Skip only when absent.
    try {
      execFileSync('python3', [EMITTER.pathname, '--check'], {
        cwd: new URL('../../../apps/crq-python/', import.meta.url).pathname,
        stdio: 'pipe',
      });
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return;
      throw error;
    }
  });
});
